import{_ as a,C as o,o as r,c as n,j as t,a as i,E as d,ak as h}from"./chunks/framework.sV-XtlWr.js";const k=JSON.parse('{"title":"Scenario gaps","description":"","frontmatter":{"title":"Scenario gaps","lang":"en-US"},"headers":[],"relativePath":"features/scenario-gaps.md","filePath":"features/scenario-gaps.md","lastUpdated":1790197318000}'),c={name:"features/scenario-gaps.md"};function l(p,e,g,u,m,f){const s=o("Needs");return r(),n("div",null,[e[0]||(e[0]=t("h1",{id:"scenario-gaps",tabindex:"-1"},[i("Scenario gaps "),t("a",{class:"header-anchor",href:"#scenario-gaps","aria-label":'Permalink to "Scenario gaps"'},"​")],-1)),d(s,{reporter:""}),e[1]||(e[1]=h(`<p>The catalog lists the tests you have. <strong>Scenario gaps</strong> describe the ones you don&#39;t — the routes no test requests, the pages nothing visits, the changed file no test reaches. Each gap is a suggestion with its evidence and a next step, never a verdict.</p><p>Everything here is built from what the reporter already captures, joined into <strong>one graph per project</strong>. With history and an SCM token, it works with zero setup.</p><blockquote><p><strong>Observed reach, not coverage.</strong> A gap says a test <em>observably reached</em> something, or that nothing did — measured from real runs, never from instrumented code coverage. &quot;No edge&quot; means &quot;no evidence&quot;, not &quot;proof of absence&quot;.</p></blockquote><h2 id="uncovered-changes-on-a-pull-request" tabindex="-1">Uncovered changes on a pull request <a class="header-anchor" href="#uncovered-changes-on-a-pull-request" aria-label="Permalink to &quot;Uncovered changes on a pull request&quot;">​</a></h2><p>When a pull-request-stamped run finishes, Piwi joins the changed files to the tests that reach them and adds an <strong>Uncovered changes</strong> section to the <a href="/guide/ci.html#pull-request-feedback">pull-request comment</a>, grouped by ticket:</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">#### 🟣 Uncovered changes · 3 of 7 files · 2 tickets</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Observed reach, not instrumented coverage. This run and the last 30 on </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`main\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**PROJ-418**</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \`server/api/orders/[id].patch.ts\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> · changed (+41 −3) · 0 tests in 30 runs</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  → </span><span style="--shiki-light:#24292E;--shiki-light-font-style:italic;--shiki-dark:#E1E4E8;--shiki-dark-font-style:italic;">*a scenario that exercises [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">id</span><span style="--shiki-light:#24292E;--shiki-light-font-style:italic;--shiki-dark:#E1E4E8;--shiki-dark-font-style:italic;">].patch.ts*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> · draft</span></span></code></pre></div><p>&quot;No test in this run&quot; is always paired with the count from recent history, so a run narrowed by a <a href="/guide/test-selection.html">selection</a> is never mistaken for a gap. With no SCM token or no diff, the section does not appear. Tickets come from the commit messages and the pull request. Change coverage is also available on demand:</p><ul><li><strong>API</strong> — <code>GET /api/projects/{id}/gaps/change-coverage?run={runId}</code>, or <code>?base={sha}&amp;head={sha}</code> for an explicit range.</li><li><strong>MCP</strong> — <a href="/features/mcp.html"><code>get_change_coverage</code></a> reads what a branch left untested, <a href="/features/mcp.html"><code>list_scenario_gaps</code></a> lists the ranked gaps (by class, feature, score or PR) and <a href="/features/mcp.html"><code>draft_scenario</code></a> turns one into a deterministic skeleton. The <strong>write-the-missing-test</strong> skill drives the loop for an agent.</li></ul><h2 id="the-detectors" tabindex="-1">The detectors <a class="header-anchor" href="#the-detectors" aria-label="Permalink to &quot;The detectors&quot;">​</a></h2><p>Beyond change time, detectors read the graph and history, each naming its evidence and a next step:</p><table tabindex="0"><thead><tr><th>Detector</th><th>Finds</th><th>Example evidence</th></tr></thead><tbody><tr><td><strong>Changed, unreached</strong></td><td>a changed source file no test reaches</td><td><code>+41 −3 · no test in run #812 · 0 in 30 runs</code></td></tr><tr><td><strong>Success only</strong></td><td>a route observed only with 2xx/3xx — its error paths never exercised</td><td><code>Observed 412 times, always 200</code></td></tr><tr><td><strong>Single covering test</strong></td><td>a node exactly one test reaches — one flaky test from no coverage</td><td><code>Only checkout › coupon reaches this</code></td></tr><tr><td><strong>Surface drift</strong></td><td>a route or page first seen in the latest run — surface the suite may not exercise yet</td><td><code>/billing/plans appeared in run #830</code></td></tr><tr><td><strong>Control nobody exercises</strong></td><td>a control on a page no locator ever targets</td><td><code>On 12 pages · no locator targets it</code></td></tr><tr><td><strong>Reachable, unvisited</strong></td><td>a linked page no test navigates to</td><td><code>Linked from 7 pages · never navigated to</code></td></tr><tr><td><strong>API-only route</strong></td><td>a route only request fixtures reach — no control triggers it, no page loads it</td><td><code>reached only by request fixtures</code></td></tr><tr><td><strong>Not noticed</strong></td><td>a route a probe broke while every test passed — the most dangerous class</td><td><code>Passes with 500 on POST /api/orders</code></td></tr><tr><td><strong>Orphan test</strong></td><td>a test whose every reached node vanished from recent runs</td><td><code>3 pages it reaches disappeared 40 days ago</code></td></tr><tr><td><strong>Fix did not hold</strong></td><td>a failure cluster whose fix later regressed</td><td><code>Fixed in a1b2c3d · regressed 6 days later</code></td></tr></tbody></table><p>More detectors — phantom coverage, passed-with-errors, an uncalled method, assertion-light pages, change-time ones — are implemented but <strong>not yet wired</strong>. Each gap names its class: <strong>blind-spot</strong> (nothing reaches it), <strong>false-comfort</strong> (a probe found it unnoticed) or <strong>fragile</strong> (one flaky or skipped test).</p><h2 id="the-whole-suite-not-just-its-routes" tabindex="-1">The whole suite, not just its routes <a class="header-anchor" href="#the-whole-suite-not-just-its-routes" aria-label="Permalink to &quot;The whole suite, not just its routes&quot;">​</a></h2><p>The graph also holds the <strong>controls</strong> and <strong>links</strong> each page exposes (templated names, at most 200 per page, from the <strong>page inventory</strong> the reporter records on passing runs — <code>capturePageInventory</code>, <strong>off by default</strong>, names and hrefs only) and the <strong>handler</strong> and <strong>dependency</strong> each route reaches, from the server spans instrumentation forwards. Control and link nodes, and the detectors that read them, appear only once <code>capturePageInventory</code> is enabled.</p><h2 id="declared-surface" tabindex="-1">Declared surface <a class="header-anchor" href="#declared-surface" aria-label="Permalink to &quot;Declared surface&quot;">​</a></h2><p>Beyond what tests observe, Piwi can hold what the application <em>declares</em> it exposes, so a route or page nothing reaches is named a <strong>declared, never hit</strong> blind spot instead of staying invisible. Three independent ramps feed graph nodes with origin <code>manifest</code> or <code>openapi</code>:</p><ul><li><strong>Instrumentation.</strong> The Nitro and ASP.NET Core packages serve a route manifest at <code>/__piwi/manifest</code> outside production. The reporter&#39;s global setup fetches it once a base URL is configured and the app&#39;s first response carries an instrumentation header, and uploads it with the run.</li><li><strong>A committed manifest.</strong> A <code>piwi.manifest.json</code> next to your Playwright config (<code>{ routes: [...], pages: [...] }</code>) is uploaded whenever present.</li><li><strong>An OpenAPI URL.</strong> Set one per project; Piwi fetches it server-side and records each route&#39;s documented response codes, so <strong>success only</strong> can name the error codes a route documents but never returned.</li></ul><h2 id="probing-what-a-test-would-notice" tabindex="-1">Probing what a test would notice <a class="header-anchor" href="#probing-what-a-test-would-notice" aria-label="Permalink to &quot;Probing what a test would notice&quot;">​</a></h2><p>Reach says a test touched a route, not that it would fail if the route returned garbage — many passing tests would not. <code>piwi probe</code> replays a passing test with a fault at the Playwright boundary (a 500, an empty body, a dropped field, a stale value, a slow response) and records whether it noticed:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @piwitests/reporter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> probe</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-project</span></span></code></pre></div><p>It fetches the exposure-ranked plan — never-probed pairs first, one fault per test, a budget — applies the faults and posts the outcomes. A probe run never counts as a real run; a route that stays green under a fault becomes a <strong>not noticed</strong> gap.</p><h3 id="server-probes-level-two" tabindex="-1">Server probes (level two) <a class="header-anchor" href="#server-probes-level-two" aria-label="Permalink to &quot;Server probes (level two)&quot;">​</a></h3><p><strong>Experimental and unreleased.</strong> The entry condition below is not yet measured, so this level stays off by default.</p><p>A client probe rewrites the response in the browser, so the server never runs its error path. A <strong>server probe</strong> signs a fault onto one request (<code>X-Piwi-Probe</code>, HMAC-signed with <code>PIWI_PROBE_SECRET</code>) and the instrumentation applies it inside the server — a thrown error, a status, a delay, a mutated response, or a failed dependency call — reporting the fault it applied, so an un-honored probe records as <em>inconclusive</em>, never a pass. Two signals come back: whether the test noticed (a <code>checks</code> edge) and whether the application degraded — a <strong>resilience finding</strong> (class <code>unhandled</code> or <code>degraded</code>, ranked by exposure × severity), plus the <strong>unprobed dependency</strong> and <strong>not handled</strong> detectors.</p><p>The level stays behind a per-project flag, honored only outside production, with fault classes and routes allow-listed and dependency faults on state-changing routes off by default. Turn it on once client probes report <em>not noticed</em> on one in ten probed pairs — the sign of false comfort the network boundary cannot reveal.</p><h2 id="exposure-ranking" tabindex="-1">Exposure ranking <a class="header-anchor" href="#exposure-ranking" aria-label="Permalink to &quot;Exposure ranking&quot;">​</a></h2><p>Gaps are ranked by an explicit <strong>exposure</strong> score, not a raw count — a percentage over an observed surface looks complete exactly when the surface is sparse. Four factors, each in <code>[0.1, 1]</code> so a missing input never zeroes a row, all shown on the gap: <strong>churn</strong> (commits in the last 90 days), <strong>age</strong> (older components weigh <em>up</em>, where escaped defects concentrate), <strong>escape history</strong> (the file is in a cluster&#39;s fixing commit) and <strong>priority</strong>. The score is the geometric mean of the factors, times the detector&#39;s confidence.</p><h2 id="what-the-graph-includes" tabindex="-1">What the graph includes <a class="header-anchor" href="#what-the-graph-includes" aria-label="Permalink to &quot;What the graph includes&quot;">​</a></h2><p>The graph stays proportional to the application&#39;s surface, not its data volume:</p><ul><li><strong>Your own origin only.</strong> Route nodes come from requests to the run&#39;s Playwright <code>baseURL</code> — analytics beacons and CDN assets never become nodes.</li><li><strong>Pages are path patterns.</strong> <code>/orders/123</code> and <code>/orders/456</code> are one node, as is the same path from staging and production.</li><li><strong>Branches stay separate.</strong> A default-branch run writes the canonical graph; any other branch writes rows tagged with it, so a route added on a pull request never shows as drift on the default branch. Those rows drop when the pull request closes.</li></ul><h2 id="the-gaps-tab-and-the-graph-view" tabindex="-1">The Gaps tab and the graph view <a class="header-anchor" href="#the-gaps-tab-and-the-graph-view" aria-label="Permalink to &quot;The Gaps tab and the graph view&quot;">​</a></h2><p>The project page has a <strong>Gaps</strong> tab: gaps and findings grouped by feature and ranked, each with its class, score factors and evidence, and the inbox verbs — <strong>accept</strong> (copies a draft skeleton to your clipboard), <strong>snooze</strong> (a day, a week, or until the node changes), <strong>dismiss</strong> with a reason (<em>not worth testing</em>, <em>covered elsewhere</em> — recording the covering test as a manual reaches edge — or <em>wrong</em>), and <strong>covered by</strong> without dismissing. Home lists accepted-but-unwritten gaps older than a week. The Test Map and its server probes are optional: <a href="/guide/getting-started.html#declining-a-capability">decline</a> either per project or instance-wide and these surfaces disappear.</p><p>The tab opens on the <strong>feature map</strong>: one circle per feature (from the <code>piwi:feature</code> tag), sized by the routes, pages and controls it groups, colored by its worst open gap, linked to the features it shares nodes with. The ranked list beside it carries every feature, however many. API: <code>GET /api/projects/{id}/feature-map</code>.</p><p>A feature or a gap&#39;s node opens in the <strong>feature graph</strong>: the node in the middle, what leads into it on the left, what it leads to on the right, nodes colored by class, edges by kind. The picture shows each kind&#39;s most severe few; the <strong>inspector</strong> under it lists every neighbor with its relation, worst gap and reaching tests. Click to recenter. API: <code>GET /api/projects/{id}/graph?node=route:POST /api/orders&amp;depth=2</code> or the <a href="/features/mcp.html"><code>get_feature_graph</code></a> MCP tool.</p><h2 id="precision-muting-and-the-digest" tabindex="-1">Precision, muting and the digest <a class="header-anchor" href="#precision-muting-and-the-digest" aria-label="Permalink to &quot;Precision, muting and the digest&quot;">​</a></h2><p>Every triage verdict is a labeled example: accepted and covered-by count <em>for</em> a detector, dismissed-as-wrong <em>against</em>. A detector below 60% precision on a project with twenty or more verdicts <strong>mutes itself</strong> there — its rows drop out of the pull-request comment first, and the Gaps tab and the admin <strong>About</strong> page say so. A weekly <strong>digest</strong> of the top new gaps per project is <strong>planned</strong> — the selection ships today; delivery through your <a href="/features/notifications.html">notification channels</a> is not yet wired.</p><h2 id="triage" tabindex="-1">Triage <a class="header-anchor" href="#triage" aria-label="Permalink to &quot;Triage&quot;">​</a></h2><p>Gaps persist so triage survives recomputation: a dismissed gap keeps its verdict, and a gap <strong>closes itself</strong> when its node gains a trusted test — so &quot;closed this month&quot; is real. List them at <code>GET /api/projects/{id}/gaps</code>, triage at <code>POST /api/projects/{id}/gaps/{gapId}/triage</code>, recompute at <code>POST /api/projects/{id}/gaps/recompute</code>.</p><h2 id="what-this-is-not" tabindex="-1">What this is not <a class="header-anchor" href="#what-this-is-not" aria-label="Permalink to &quot;What this is not&quot;">​</a></h2><ul><li><strong>Not coverage.</strong> Every surface says <em>observed reach</em>.</li><li><strong>Not a test generator.</strong> A gap proposes a scenario; the assertion is yours.</li><li><strong>Not a gate.</strong> The <code>maxUncoveredChanges</code> gate policy is off by default and warn-only — it reports uncovered changed files without changing the verdict.</li><li><strong>Not a percentage.</strong> Counts per class, ranked by exposure.</li></ul>`,40))])}const y=a(c,[["render",l]]);export{k as __pageData,y as default};
